func (syncConnectionL) LoadConnectionNidSyncConnectionRooms(ctx context.Context, e boil.ContextExecutor, singular bool, maybeSyncConnection any, mods queries.Applicator) error {
	var slice []*SyncConnection
	var object *SyncConnection

	if singular {
		var ok bool
		object, ok = maybeSyncConnection.(*SyncConnection)
		if !ok {
			object = new(SyncConnection)
			ok = queries.SetFromEmbeddedStruct(&object, &maybeSyncConnection)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", object, maybeSyncConnection))
			}
		}
	} else {
		s, ok := maybeSyncConnection.(*[]*SyncConnection)
		if ok {
			slice = *s
		} else {
			ok = queries.SetFromEmbeddedStruct(&slice, maybeSyncConnection)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", slice, maybeSyncConnection))
			}
		}
	}

	args := make(map[any]struct{})
	if singular {
		if object.R == nil {
			object.R = &syncConnectionR{}
		}
		args[object.ConnectionNid] = struct{}{}
	} else {
		for _, obj := range slice {
			if obj.R == nil {
				obj.R = &syncConnectionR{}
			}
			args[obj.ConnectionNid] = struct{}{}
		}
	}

	if len(args) == 0 {
		return nil
	}

	argsSlice := make([]any, len(args))
	i := 0
	for arg := range args {
		argsSlice[i] = arg
		i++
	}

	query := NewQuery(
		qm.From(`sync_connection_rooms`),
		qm.WhereIn(`sync_connection_rooms.connection_nid in ?`, argsSlice...),
	)
	if mods != nil {
		mods.Apply(query)
	}

	results, err := query.QueryContext(ctx, e)
	if err != nil {
		return errors.Wrap(err, "failed to eager load sync_connection_rooms")
	}

	var resultSlice []*SyncConnectionRoom
	if err = queries.Bind(results, &resultSlice); err != nil {
		return errors.Wrap(err, "failed to bind eager loaded slice sync_connection_rooms")
	}

	if err = results.Close(); err != nil {
		return errors.Wrap(err, "failed to close results in eager load on sync_connection_rooms")
	}
	if err = results.Err(); err != nil {
		return errors.Wrap(err, "error occurred during iteration of eager loaded relations for sync_connection_rooms")
	}

	if len(syncConnectionRoomAfterSelectHooks) != 0 {
		for _, obj := range resultSlice {
			if err := obj.doAfterSelectHooks(ctx, e); err != nil {
				return err
			}
		}
	}
	if singular {
		object.R.ConnectionNidSyncConnectionRooms = resultSlice
		for _, foreign := range resultSlice {
			if foreign.R == nil {
				foreign.R = &syncConnectionRoomR{}
			}
			foreign.R.ConnectionNidSyncConnection = object
		}
		return nil
	}

	for _, foreign := range resultSlice {
		for _, local := range slice {
			if local.ConnectionNid == foreign.ConnectionNid {
				local.R.ConnectionNidSyncConnectionRooms = append(local.R.ConnectionNidSyncConnectionRooms, foreign)
				if foreign.R == nil {
					foreign.R = &syncConnectionRoomR{}
				}
				foreign.R.ConnectionNidSyncConnection = local
				break
			}
		}
	}

	return nil
}

// SetTenant of the syncConnection to the related item.
// Sets o.R.Tenant to related.
// Adds o to related.R.SyncConnections.
func (o *SyncConnection) SetTenant(ctx context.Context, exec boil.ContextExecutor, insert bool, related *Tenant) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"sync_connections\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"tenant_id"}),
		strmangle.WhereClause("\"", "\"", 2, syncConnectionPrimaryKeyColumns),
	)
	values := []any{related.ID, o.ConnectionNid}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	o.TenantID = related.ID
	if o.R == nil {
		o.R = &syncConnectionR{
			Tenant: related,
		}
	} else {
		o.R.Tenant = related
	}

	if related.R == nil {
		related.R = &tenantR{
			SyncConnections: SyncConnectionSlice{o},
		}
	} else {
		related.R.SyncConnections = append(related.R.SyncConnections, o)
	}

	return nil
}

// AddConnectionNidSyncConnectionRooms adds the given related objects to the existing relationships
// of the sync_connection, optionally inserting them as new records.
// Appends related to o.R.ConnectionNidSyncConnectionRooms.
// Sets related.R.ConnectionNidSyncConnection appropriately.
func (o *SyncConnection) AddConnectionNidSyncConnectionRooms(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*SyncConnectionRoom) error {
	var err error
	for _, rel := range related {
		if insert {
			rel.ConnectionNid = o.ConnectionNid
			if err = rel.Insert(ctx, exec, boil.Infer()); err != nil {
				return errors.Wrap(err, "failed to insert into foreign table")
			}
		} else {
			updateQuery := fmt.Sprintf(
				"UPDATE \"sync_connection_rooms\" SET %s WHERE %s",
				strmangle.SetParamNames("\"", "\"", 1, []string{"connection_nid"}),
				strmangle.WhereClause("\"", "\"", 2, syncConnectionRoomPrimaryKeyColumns),
			)
			values := []any{o.ConnectionNid, rel.ConnectionNid, rel.RoomNid, rel.Pending}

			if boil.IsDebug(ctx) {
				writer := boil.DebugWriterFrom(ctx)
				fmt.Fprintln(writer, updateQuery)
				fmt.Fprintln(writer, values)
			}
			if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
				return errors.Wrap(err, "failed to update foreign table")
			}

			rel.ConnectionNid = o.ConnectionNid
		}
	}

	if o.R == nil {
		o.R = &syncConnectionR{
			ConnectionNidSyncConnectionRooms: related,
		}
	} else {
		o.R.ConnectionNidSyncConnectionRooms = append(o.R.ConnectionNidSyncConnectionRooms, related...)
	}

	for _, rel := range related {
		if rel.R == nil {
			rel.R = &syncConnectionRoomR{
				ConnectionNidSyncConnection: o,
			}
		} else {
			rel.R.ConnectionNidSyncConnection = o
		}
	}
	return nil
}

// SyncConnections retrieves all the records using an executor.
func SyncConnections(mods ...qm.QueryMod) syncConnectionQuery {
	mods = append(mods, qm.From("\"sync_connections\""))
	q := NewQuery(mods...)
	if len(queries.GetSelect(q)) == 0 {
		queries.SetSelect(q, []string{"\"sync_connections\".*"})
	}

	return syncConnectionQuery{q}
}

// FindSyncConnection retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindSyncConnection(ctx context.Context, exec boil.ContextExecutor, connectionNid int64, selectCols ...string) (*SyncConnection, error) {
	syncConnectionObj := &SyncConnection{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from \"sync_connections\" where \"connection_nid\"=$1", sel,
	)

	q := queries.Raw(query, connectionNid)

	err := q.Bind(ctx, exec, syncConnectionObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "dbpostgres: unable to select from sync_connections")
	}

	if err = syncConnectionObj.doAfterSelectHooks(ctx, exec); err != nil {
		return syncConnectionObj, err
	}

	return syncConnectionObj, nil
}

// Insert a single record using an executor.
// See boil.Columns.InsertColumnSet documentation to understand column list inference for inserts.
func (o *SyncConnection) Insert(ctx context.Context, exec boil.ContextExecutor, columns boil.Columns) error {
	if o == nil {
		return errors.New("dbpostgres: no sync_connections provided for insertion")
	}

	var err error
	if !boil.TimestampsAreSkipped(ctx) {
		currTime := time.Now().In(boil.GetLocation())

		if o.CreatedAt.IsZero() {
			o.CreatedAt = currTime
		}
	}

	if err := o.doBeforeInsertHooks(ctx, exec); err != nil {
		return err
	}

	nzDefaults := queries.NonZeroDefaultSet(syncConnectionColumnsWithDefault, o)

	key := makeCacheKey(columns, nzDefaults)
	syncConnectionInsertCacheMut.RLock()
	cache, cached := syncConnectionInsertCache[key]
	syncConnectionInsertCacheMut.RUnlock()

	if !cached {
		wl, returnColumns := columns.InsertColumnSet(
			syncConnectionAllColumns,
			syncConnectionColumnsWithDefault,
			syncConnectionColumnsWithoutDefault,
			nzDefaults,
		)

		cache.valueMapping, err = queries.BindMapping(syncConnectionType, syncConnectionMapping, wl)
		if err != nil {
			return err
		}
		cache.retMapping, err = queries.BindMapping(syncConnectionType, syncConnectionMapping, returnColumns)
		if err != nil {
			return err
		}
		if len(wl) != 0 {
			cache.query = fmt.Sprintf("INSERT INTO \"sync_connections\" (\"%s\") %%sVALUES (%s)%%s", strings.Join(wl, "\",\""), strmangle.Placeholders(dialect.UseIndexPlaceholders, len(wl), 1, 1))
		} else {
			cache.query = "INSERT INTO \"sync_connections\" %sDEFAULT VALUES%s"
		}

		var queryOutput, queryReturning string

		if len(cache.retMapping) != 0 {
			queryReturning = fmt.Sprintf(" RETURNING \"%s\"", strings.Join(returnColumns, "\",\""))
		}

		cache.query = fmt.Sprintf(cache.query, queryOutput, queryReturning)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	vals := queries.ValuesFromMapping(value, cache.valueMapping)

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, cache.query)
		fmt.Fprintln(writer, vals)
	}

	if len(cache.retMapping) != 0 {
		err = exec.QueryRowContext(ctx, cache.query, vals...).Scan(queries.PtrsFromMapping(value, cache.retMapping)...)
	} else {
		_, err = exec.ExecContext(ctx, cache.query, vals...)
	}

	if err != nil {
		return errors.Wrap(err, "dbpostgres: unable to insert into sync_connections")
	}

	if !cached {
		syncConnectionInsertCacheMut.Lock()
		syncConnectionInsertCache[key] = cache
		syncConnectionInsertCacheMut.Unlock()
	}

	return o.doAfterInsertHooks(ctx, exec)
}

// Update uses an executor to update the SyncConnection.
// See boil.Columns.UpdateColumnSet documentation to understand column list inference for updates.
// Update does not automatically update the record in case of default values. Use .Reload() to refresh the records.
func (o *SyncConnection) Update(ctx context.Context, exec boil.ContextExecutor, columns boil.Columns) (int64, error) {
	var err error
	if err = o.doBeforeUpdateHooks(ctx, exec); err != nil {
		return 0, err
	}
	key := makeCacheKey(columns, nil)
	syncConnectionUpdateCacheMut.RLock()
	cache, cached := syncConnectionUpdateCache[key]
	syncConnectionUpdateCacheMut.RUnlock()

	if !cached {
		wl := columns.UpdateColumnSet(
			syncConnectionAllColumns,
			syncConnectionPrimaryKeyColumns,
		)

		if !columns.IsWhitelist() {
			wl = strmangle.SetComplement(wl, []string{"created_at"})
		}
		if len(wl) == 0 {
			return 0, errors.New("dbpostgres: unable to update sync_connections, could not build whitelist")
		}

		cache.query = fmt.Sprintf("UPDATE \"sync_connections\" SET %s WHERE %s",
			strmangle.SetParamNames("\"", "\"", 1, wl),
			strmangle.WhereClause("\"", "\"", len(wl)+1, syncConnectionPrimaryKeyColumns),
		)
		cache.valueMapping, err = queries.BindMapping(syncConnectionType, syncConnectionMapping, append(wl, syncConnectionPrimaryKeyColumns...))
		if err != nil {
			return 0, err
		}
	}

	values := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(o)), cache.valueMapping)

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, cache.query)
		fmt.Fprintln(writer, values)
	}
	var result sql.Result
	result, err = exec.ExecContext(ctx, cache.query, values...)
	if err != nil {
		return 0, errors.Wrap(err, "dbpostgres: unable to update sync_connections row")
	}

	rowsAff, err := result.RowsAffected()
	if err != nil {
		return 0, errors.Wrap(err, "dbpostgres: failed to get rows affected by update for sync_connections")
	}

	if !cached {
		syncConnectionUpdateCacheMut.Lock()
		syncConnectionUpdateCache[key] = cache
		syncConnectionUpdateCacheMut.Unlock()
	}

	return rowsAff, o.doAfterUpdateHooks(ctx, exec)
}

