// Reload refetches the object from the database
// using the primary keys with an executor.
func (o *SyncConnection) Reload(ctx context.Context, exec boil.ContextExecutor) error {
	ret, err := FindSyncConnection(ctx, exec, o.ConnectionNid)
	if err != nil {
		return err
	}

	*o = *ret
	return nil
}

// ReloadAll refetches every row with matching primary key column values
// and overwrites the original object slice with the newly updated slice.
func (o *SyncConnectionSlice) ReloadAll(ctx context.Context, exec boil.ContextExecutor) error {
	if o == nil || len(*o) == 0 {
		return nil
	}

	slice := SyncConnectionSlice{}
	var args []any
	for _, obj := range *o {
		pkeyArgs := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(obj)), syncConnectionPrimaryKeyMapping)
		args = append(args, pkeyArgs...)
	}

	sql := "SELECT \"sync_connections\".* FROM \"sync_connections\" WHERE " +
		strmangle.WhereClauseRepeated(string(dialect.LQ), string(dialect.RQ), 1, syncConnectionPrimaryKeyColumns, len(*o))

	q := queries.Raw(sql, args...)

	err := q.Bind(ctx, exec, &slice)
	if err != nil {
		return errors.Wrap(err, "dbpostgres: unable to reload all in SyncConnectionSlice")
	}

	*o = slice

	return nil
}

// SyncConnectionExists checks if the SyncConnection row exists.
func SyncConnectionExists(ctx context.Context, exec boil.ContextExecutor, connectionNid int64) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from \"sync_connections\" where \"connection_nid\"=$1 limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, connectionNid)
	}
	row := exec.QueryRowContext(ctx, sql, connectionNid)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "dbpostgres: unable to check if sync_connections exists")
	}

	return exists, nil
}

// Exists checks if the SyncConnection row exists.
func (o *SyncConnection) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return SyncConnectionExists(ctx, exec, o.ConnectionNid)
}
